/* САПЁР — классика на клетках листа.
   Поле рисуется с B3: клетки квадратные, закрытые — серые. Щелчок по клетке
   меняет выделение, плагин ловит это событием «приВыделении», открывает клетку
   и отводит курсор на «стоянку» (A2) — тогда следующий щелчок снова даст событие.
   Флажок — правой кнопкой (пункт меню клетки) или переключателем «ставит флажок».
   Партия хранится в памяти листа: закрыли панель или книгу — продолжите с того же места. */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}

const УРОВНИ = {
  'Новичок — 9×9, 10 мин':    {ключ: 'Новичок',  строк: 9,  столбцов: 9,  мин: 10},
  'Любитель — 16×16, 40 мин': {ключ: 'Любитель', строк: 16, столбцов: 16, мин: 40},
  'Профи — 16×30, 99 мин':    {ключ: 'Профи',    строк: 16, столбцов: 30, мин: 99},
};
const Р0 = 2, С0 = 1;               /* поле с B3 */
const СТОЯНКА = {r: 1, c: 0};      /* A2 — рядом с полем, но не в нём */
const ЦИФРЫ = ['', '#1d4ed8', '#15803d', '#dc2626', '#1e3a8a', '#9a3412', '#0e7490', '#111827', '#6b7280'];
const ОСНОВА = {b: 1, size: 12, align: 'center', valign: 'middle'};
/* Клетки — шахматной раскраской в два тона: рамки у залитых клеток приложение
   не показывает (заливка ложится поверх), а так плитки различимы и без рамок. */
const ЗАКРЫТА = Object.assign({fill: '#bfcad8', color: '#bfcad8'}, ОСНОВА), ЗАКРЫТА2 = Object.assign({}, ЗАКРЫТА, {fill: '#b2bfd0', color: '#b2bfd0'});
const ОТКРЫТА = Object.assign({fill: '#f6f8fb'}, ОСНОВА), ОТКРЫТА2 = Object.assign({}, ОТКРЫТА, {fill: '#edf1f6'});
const тон = (i, а, б) => ((Math.floor(i / игра.столбцов) + i % игра.столбцов) % 2 ? б : а);
const ПАМЯТЬ = 'сапёр';

let игра = null;        /* {лист, ключ, строк, столбцов, мин, мины[], открыто[], флажки[], секунд, конец} */
let тик = null, сНачала = 0;

/* --- состояние ------------------------------------------------------------ */
const N = () => игра.строк * игра.столбцов;
const индекс = (r, c) => r * игра.столбцов + c;
function соседи(i){
  const r = Math.floor(i / игра.столбцов), c = i % игра.столбцов, out = [];
  for(let dr = -1; dr <= 1; dr++) for(let dc = -1; dc <= 1; dc++){
    if(!dr && !dc) continue;
    const rr = r + dr, cc = c + dc;
    if(rr >= 0 && cc >= 0 && rr < игра.строк && cc < игра.столбцов) out.push(индекс(rr, cc));
  }
  return out;
}
const минаЛи = i => игра.мины && игра.мины[i] === 1;
const рядом = i => соседи(i).reduce((s, j) => s + (минаЛи(j) ? 1 : 0), 0);
function сохранить(){ лист(игра.лист).запомнить(ПАМЯТЬ, Object.assign({}, игра, {секунд: прошло()})); }
function прошло(){ return игра && игра.мины && !игра.конец && сНачала ? Math.floor((Date.now() - сНачала) / 1000) : (игра ? игра.секунд || 0 : 0); }

/* --- рисование ------------------------------------------------------------ */
function нарисоватьКлетку(i){
  const r = Р0 + Math.floor(i / игра.столбцов), c = С0 + i % игра.столбцов, к = клетка(r, c);
  const откр = тон(i, ОТКРЫТА, ОТКРЫТА2), закр = тон(i, ЗАКРЫТА, ЗАКРЫТА2);
  if(игра.открыто[i]){
    if(минаЛи(i)){ к.значение = '●'; к.стиль = Object.assign({}, откр, игра.взрыв === i ? {fill: '#f87171'} : {}, {color: '#111827'}); return; }
    const n = рядом(i);
    к.значение = n ? n : '';
    к.стиль = Object.assign({}, откр, {color: ЦИФРЫ[n] || '#111827'});
    return;
  }
  if(игра.флажки[i]){
    const неверно = игра.конец && !минаЛи(i);
    к.значение = неверно ? '✕' : '⚑';
    к.стиль = Object.assign({}, закр, {color: '#dc2626'});
    return;
  }
  if(игра.конец === 'взрыв' && минаЛи(i)){ к.значение = '●'; к.стиль = Object.assign({}, закр, {color: '#111827'}); return; }
  к.значение = '';
  к.стиль = закр;
}
function шапка(){
  const ост = игра.мин - игра.флажки.reduce((s, x) => s + x, 0);
  const к = клетка(0, С0);
  к.значение = 'Сапёр · ' + игра.ключ + ' · мин: ' + игра.мин + ' · флажков: ' + (игра.мин - ост)
    + (игра.конец === 'победа' ? ' · ПОБЕДА за ' + ВРЕМЯ(игра.секунд) : игра.конец === 'взрыв' ? ' · взрыв' : '');
  к.стиль = {b: 1, size: 12, color: игра.конец === 'победа' ? '#15803d' : игра.конец === 'взрыв' ? '#b91c1c' : '#151c2e'};
}
function нарисоватьВсё(){
  for(let i = 0; i < N(); i++) нарисоватьКлетку(i);
  шапка();
}
function показатьСчёт(){
  if(!игра){ панель.список('сейчас', [['Игра', 'не начата — нажмите «Новая игра»']]); return; }
  const флажков = игра.флажки.reduce((s, x) => s + x, 0);
  панель.список('сейчас', [
    ['Уровень', игра.ключ], ['Мин осталось', String(игра.мин - флажков)],
    ['Время', ВРЕМЯ(прошло())],
    ['Итог', игра.конец === 'победа' ? 'победа!' : игра.конец === 'взрыв' ? 'взрыв — попробуйте ещё' : игра.мины ? 'идёт' : 'ждёт первого щелчка'],
  ]);
}
function показатьРекорды(){
  const р = хранилище.взять('рекорды', {}) || {};
  панель.список('рекорды', ['Новичок', 'Любитель', 'Профи'].map(к => [к, р[к] != null ? ВРЕМЯ(р[к]) : '—']));
}
function часы(вкл){
  if(вкл && !тик) тик = setInterval(показатьСчёт, 1000);
  if(!вкл && тик){ clearInterval(тик); тик = null; }
}

/* --- ход ------------------------------------------------------------------ */
function разложитьМины(первая){
  const нельзя = new Set([первая, ...соседи(первая)]);
  const свободные = [];
  for(let i = 0; i < N(); i++) if(!нельзя.has(i)) свободные.push(i);
  игра.мины = new Array(N()).fill(0);
  for(let k = 0; k < игра.мин && свободные.length; k++){
    const j = Math.floor(Math.random() * свободные.length);
    игра.мины[свободные[j]] = 1; свободные.splice(j, 1);
  }
  сНачала = Date.now(); часы(true);
}
function открыть(i, изменённые){
  if(игра.открыто[i] || игра.флажки[i]) return;
  /* заливка пустых — очередью, без рекурсии: поле 16×30 рекурсия выдержит, но зачем рисковать */
  const очередь = [i];
  while(очередь.length){
    const j = очередь.pop();
    if(игра.открыто[j] || игра.флажки[j]) continue;
    игра.открыто[j] = 1; изменённые.add(j);
    if(минаЛи(j)){ игра.взрыв = j; return; }
    if(рядом(j) === 0) for(const к of соседи(j)) if(!игра.открыто[к]) очередь.push(к);
  }
}
function итогХода(изменённые){
  if(игра.взрыв !== undefined && игра.взрыв !== null && !игра.конец){
    игра.секунд = прошло(); игра.конец = 'взрыв'; часы(false);
    нарисоватьВсё(); сохранить(); показатьСчёт();
    панель.сообщение('Взрыв! Мины показаны, неверные флажки помечены ✕. «Новая игра» — ещё раз.');
    return;
  }
  const открыто = игра.открыто.reduce((s, x) => s + x, 0);
  if(открыто === N() - игра.мин){
    игра.секунд = прошло(); игра.конец = 'победа'; часы(false);
    for(let i = 0; i < N(); i++) if(минаЛи(i)) игра.флажки[i] = 1;
    нарисоватьВсё(); сохранить(); показатьСчёт();
    const р = хранилище.взять('рекорды', {}) || {};
    const было = р[игра.ключ];
    if(было == null || игра.секунд < было){ р[игра.ключ] = игра.секунд; хранилище.положить('рекорды', р); показатьРекорды();
      панель.сообщение('Победа за ' + ВРЕМЯ(игра.секунд) + ' — новый рекорд уровня «' + игра.ключ + '»!'); }
    else панель.сообщение('Победа за ' + ВРЕМЯ(игра.секунд) + '. Рекорд уровня — ' + ВРЕМЯ(было) + '.');
    return;
  }
  for(const j of изменённые) нарисоватьКлетку(j);
  шапка(); сохранить(); показатьСчёт();
}
function ходОткрыть(i){
  if(!игра.мины) разложитьМины(i);
  const изм = new Set();
  открыть(i, изм);
  итогХода(изм);
}
function ходФлажок(i){
  if(игра.открыто[i]) return;
  игра.флажки[i] = игра.флажки[i] ? 0 : 1;
  нарисоватьКлетку(i); шапка(); сохранить(); показатьСчёт();
}
function ходСоседи(i){
  if(!игра.открыто[i] || !игра.мины) return;
  const n = рядом(i), ф = соседи(i).reduce((s, j) => s + (игра.флажки[j] ? 1 : 0), 0);
  if(!n || ф !== n){ панель.сообщение('Соседей открывают, когда флажков вокруг столько же, сколько показывает цифра (' + n + ').'); return; }
  const изм = new Set();
  for(const j of соседи(i)) открыть(j, изм);
  итогХода(изм);
}
function клеткаПоля(п){
  if(!игра || игра.конец) return null;
  const к = гдеЩелчок(п, игра.лист);
  if(!к) return null;
  const r = к.r - Р0, c = к.c - С0;
  if(r < 0 || c < 0 || r >= игра.строк || c >= игра.столбцов) return null;
  return индекс(r, c);
}

/* --- обработчики ---------------------------------------------------------- */
function Старт(){
  показатьРекорды();
  let м = null;
  try { м = лист().память(ПАМЯТЬ); } catch(e){}
  if(м && м.открыто && !м.конец){
    игра = м;
    if(игра.мины){ сНачала = Date.now() - (игра.секунд || 0) * 1000; часы(true); }
    панель.сообщение('Незаконченная партия на этом листе — продолжаем (' + игра.ключ + ').');
  }
  показатьСчёт();
}
async function НоваяИгра(){
  const п = параметры({});
  const ур = УРОВНИ[п.уровень] || УРОВНИ['Новичок — 9×9, 10 мин'];
  const имяЛиста = книга.выделение ? книга.выделение.лист : книга.листы[0];
  let своё = null;
  try { своё = лист().память(ПАМЯТЬ); } catch(e){}
  if(!своё && !(await областьПуста(0, С0, Р0 + 16, С0 + 30))){
    if(!(await диалог.вопрос('На этом листе в B1:AE19 уже что-то есть. Поле сапёра ляжет поверх. Лучше завести для игры пустой лист (+ внизу). Всё равно положить здесь?'))) return;
  }
  часы(false);
  /* прежнее поле могло быть больше — сначала стираем его */
  if(своё && своё.строк) for(let r = 0; r < своё.строк; r++) for(let c = 0; c < своё.столбцов; c++){
    const к = клетка(Р0 + r, С0 + c); к.значение = ''; к.стиль = {fill: null, color: null};
  }
  игра = {лист: имяЛиста, ключ: ур.ключ, строк: ур.строк, столбцов: ур.столбцов, мин: ур.мин, мины: null,
          открыто: new Array(ур.строк * ур.столбцов).fill(0), флажки: new Array(ур.строк * ур.столбцов).fill(0),
          секунд: 0, конец: null, взрыв: null};
  сНачала = 0;
  клеткиКвадратом(Р0, С0, Р0 + игра.строк - 1, С0 + игра.столбцов - 1, 24);
  await обновитьВысоты();
  нарисоватьВсё(); сохранить(); показатьСчёт();
  наСтоянку(СТОЯНКА.r, СТОЯНКА.c);
  панель.сообщение('Новая игра: ' + ур.ключ + '. Щёлкните любую клетку — первая всегда без мины.');
}
function Ход(){
  const п = книга.повод;
  if(этоПослеМеню(п)) return;             /* это правый щелчок: выделение пришло следом за меню */
  const i = клеткаПоля(п);
  if(i === null) return;
  if(параметры({}).режим === 'ставит флажок') ходФлажок(i); else ходОткрыть(i);
  наСтоянку(СТОЯНКА.r, СТОЯНКА.c);
}
function Меню(){
  const п = книга.повод;
  const i = клеткаПоля(п);
  if(i === null) return [];
  последнееМеню = {адрес: п.адрес, t: Date.now(), i};
  if(игра.открыто[i]) return рядом(i) ? [{имя: 'Открыть соседей', функция: 'МенюСоседи'}] : [];
  return [{имя: игра.флажки[i] ? 'Снять флажок' : 'Флажок ⚑', функция: 'МенюФлажок'}];
}
function МенюФлажок(){ if(игра && !игра.конец && последнееМеню.i != null){ ходФлажок(последнееМеню.i); наСтоянку(СТОЯНКА.r, СТОЯНКА.c); } }
function МенюСоседи(){ if(игра && !игра.конец && последнееМеню.i != null){ ходСоседи(последнееМеню.i); наСтоянку(СТОЯНКА.r, СТОЯНКА.c); } }
/* Кто-то набрал в поле или нажал «Отменить» — поле возвращается к состоянию игры. */
function Правка(){
  const п = книга.повод;
  if(!игра || п.строение || п.откуда === 'плагин') return;
  const наПоле = (п.клетки || []).some(к => к.лист === игра.лист && к.строка - 1 >= Р0 && к.строка - 1 < Р0 + игра.строк
    && к.столбец - 1 >= С0 && к.столбец - 1 < С0 + игра.столбцов);
  if(!наПоле) return;
  нарисоватьВсё();
  панель.сообщение('Поле сапёра правится только ходами — восстановил его.');
}
function СброситьРекорды(){ хранилище.положить('рекорды', {}); показатьРекорды(); панель.сообщение('Рекорды сброшены.'); }
